418	+/** Friday to the Sunday right after, for a fixed price per room type, in any season. */
419	+final class WeekendPackagePlan implements RatePlanPolicy {
420	+
421	+    private static final Map<RoomType, BigDecimal> PRICE_BY_ROOM_TYPE = Map.of(
422	+            RoomType.STANDARD, new BigDecimal("520.00"),
423	+            RoomType.DELUXE, new BigDecimal("820.00"),
424	+            RoomType.SUITE, new BigDecimal("1200.00"));
425	+    private static final BigDecimal REFUNDED_SHARE = new BigDecimal("0.5");
426	+
427	+    @Override
428	+    public void validate(Room room, NewReservation request) {
429	+        boolean fridayToSunday = request.checkIn().getDayOfWeek() == DayOfWeek.FRIDAY
430	+                && request.checkOut().equals(request.checkIn().plusDays(2));
431	+        if (!fridayToSunday) {
432	+            throw new HotelException(ErrorCode.INVALID_REQUEST,
433	+                    "the weekend package goes from a Friday to the Sunday right after");
434	+        }
435	+    }
436	+
437	+    @Override
438	+    public Price price(Room room, NewReservation request, NightlyCharges charges) {
439	+        BigDecimal packagePrice = PRICE_BY_ROOM_TYPE.get(room.type());
440	+        return new Price(charges.nights(), packagePrice, PriceCalculator.cents(BigDecimal.ZERO), packagePrice);
441	+    }
442	+
443	+    @Override
444	+    public BigDecimal refund(Reservation reservation) {
445	+        return PriceCalculator.cents(reservation.amountPaid().multiply(REFUNDED_SHARE));
446	+    }
447	+}
